/**
 * Curated provenance sidecar, schema 2 (A2-030). Stable scenario/outcome IDs are canonical;
 * labels and citation parsing never assign identity or goal coverage at runtime.
 * Source: current scenario extraction and its cited dossier sections. The exact fixture
 * expression is retained as an auditable operator, not a claim that it is the clinical
 * measurement. Multi-paper rows without a resolved source arm, opaque helper operators,
 * and unpublished heuristics stay unknown and contribute no goal-specific study count.
 * No paper-level method absent from that extraction is invented here. Inputs describe
 * the fixture, with observed inputs distinguished from prescriptions and imputations.
 * This is development evidence; no untouched external holdout is introduced.
 */
import type { Check } from './harness/types';
import type { DatasetRole, EvidenceClass, ToleranceType } from './ledger';

export interface OutcomeProvenance {
  status: 'curated' | 'unknown';
  unknown: readonly string[];
  kind: 'humanStudy' | 'conditionalDynamics' | 'verification' | 'imputation';
  sources: readonly { studyId: string; cohortId: string; armIds: readonly string[] }[];
  participatingArmIds: readonly string[];
  model: { role: DatasetRole | null; roleBasis: 'documented' | 'migrationDefault'; influenced: readonly string[]; evaluations: readonly { modelVersion: string; freezeHash: string; protocol: string; extractedAfterFreeze: boolean; attempted: number }[]; influencedVersions: readonly string[] };
  inputs: { observed: readonly string[]; protocol: readonly string[]; imputed: readonly string[] };
  scope: { population: string; studyPopulation: string; clinical: string; intervention: string; horizonDays: Readonly<Record<string, number>>; manualInputs: string };
  operator: { series: readonly string[]; transformation: string; expression: string; timeBasis: string; unit: string; estimand: string; method: string };
  tolerance: { type: ToleranceType; source: string; check: Check };
  supportedGoals: readonly string[];
}
export interface ScenarioProvenance {
  studies: readonly string[];
  evidenceClass: EvidenceClass;
  outcomes: Readonly<Record<string, OutcomeProvenance>>;
}

type Defaults = Pick<OutcomeProvenance, 'inputs' | 'model' | 'scope'>;
type Row = Omit<OutcomeProvenance, keyof Defaults> & { scope: Partial<OutcomeProvenance['scope']> & Pick<OutcomeProvenance['scope'], 'horizonDays'>; inputs?: Defaults['inputs']; model?: Defaults['model'] };
function scenario(studies: readonly string[], evidenceClass: EvidenceClass, defaults: Defaults, rows: Record<string, Row>): ScenarioProvenance {
  return { studies, evidenceClass, outcomes: Object.fromEntries(Object.entries(rows).map(([id, row]) => [id, { ...defaults, ...row, scope: { ...defaults.scope, ...row.scope } }])) };
}

